#include <bits/stdc++.h>
using namespace std;

long long MOD;

long long add_mod(long long x, long long y) {
    long long s = x + y;
    if (s >= MOD) s -= MOD;
    return s;
}

long long sub_mod(long long x, long long y) {
    if (x < y) return x - y + MOD;
    return x - y;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n >> MOD;

    vector<vector<long long>> DP(n + 1);
    DP[0] = vector<long long>(1, 1);

    for (int i = 1; i <= n; ++i) {
        int dim = i * (i - 1) / 2;
        DP[i] = vector<long long>(dim + 1, 0);
        long long sum = 0;
        for (int j = 0; j <= dim; ++j) {
            if (j < (int)DP[i - 1].size()) sum = add_mod(sum, DP[i - 1][j]);
            DP[i][j] = sum;
            if (j >= i - 1) sum = sub_mod(sum, DP[i - 1][j - i + 1]);
        }
    }

    vector<long long> pf(n * n, 0);
    long long ans = 0;

    for (int cut = 2; cut < n; ++cut) {
        int dim = cut * (cut - 1) / 2;
        for (int i = 1; i <= dim; ++i) {
            pf[i] = add_mod(pf[i - 1], DP[cut][i]);
        }

        auto range = [&](int l, int r) -> long long {
            if (l > min(r, dim)) return 0LL;
            int rr = min(r, dim);
            long long res = pf[rr];
            if (l > 0) res = sub_mod(res, pf[l - 1]);
            return res;
        };

