            }
            aux = add_mod(aux, DP[cut][x] * (cut + 1LL) % MOD);
            aux = sub_mod(aux, range(x, x + cut - 2));
        }

        for (int i = cut + 2; i <= n; ++i) {
            tot = tot * i % MOD;
        }
        ans = add_mod(ans, tot);
    }

    cout << ans << '\n';
    return 0;
