      return sub(pf[minOf(r, dim)], if (l > 0) pf[l - 1] else 0)
    }
    var (tot, aux, sum) = arrayOf(0L, 0L, 0L)
    for (x in dim downTo 0) {
      val yo = (range(x + cut + 1, dim) * (cut * (cut + 1) / 2) + sum) % MOD
      tot = add(tot, DP[cut][x] * yo % MOD)
      if (x + cut <= dim) sum = sub(sum, DP[cut][x + cut] * (cut * (cut + 1) / 2 - 1) % MOD)
      sum = add(sum, aux)
      if (x + cut - 1 <= dim) aux = sub(aux, DP[cut][x + cut - 1] * 2 % MOD)
      aux = add(aux, DP[cut][x] * (cut + 1) % MOD)
      aux = sub(aux, range(x, x + cut - 2))
    }
    for (i in (cut + 2)..n) tot = tot * i % MOD
    ans = add(ans, tot)
  }
  println(ans)
